.source-content mark { padding: 2px 0; background: #ffdd8b; color: inherit; }

.modal-layer { align-items: center; justify-content: center; padding: 24px; }
.upload-dialog { width: min(700px, 96vw); max-height: 94vh; overflow-y: auto; background: var(--paper); box-shadow: 0 30px 70px rgba(20,15,12,.3); }
.upload-dialog > header { padding: 20px 22px 16px; }
.dialog-tabs { padding: 10px 22px; display: flex; gap: 5px; border-bottom: 1px solid var(--line); }
.dialog-body { padding: 18px 22px; }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.form-grid .wide { grid-column: 1 / -1; }
.form-grid textarea { resize: vertical; line-height: 1.45; }
.format-note, .character-count { margin: -5px 0 0; color: var(--muted); font-size: .67rem; }
.character-count { text-align: right; }
.dialog-error { padding: 11px 22px; background: #fff0ee; color: #8a302d; font-size: .76rem; }
.mobile-panel-tabs { display: none; }

@media (max-width: 1120px) {
  .case-stats { display: none; }
  .topbar .wordmark { min-width: auto; }
  .topbar .wordmark small, .topbar .connection-state { display: none; }
  .workspace-grid { grid-template-columns: 230px minmax(400px, 1fr) 310px; }
}

@media (max-width: 880px) {
  .app-shell { height: 100dvh; }
  .topbar { flex-wrap: wrap; }
  .view-switch { order: 3; width: 100%; height: 34px; }
  .view-switch button { flex: 1; }
  .topbar-actions { margin-left: auto; }
  .topbar-actions .compact { padding: 5px 8px; }
  .case-bar { min-height: auto; flex-wrap: wrap; }
  .case-title { min-width: 0; }
  .investigate-button { min-width: auto; }
  .mobile-panel-tabs { display: flex; padding: 6px; background: #ece6dc; border-bottom: 1px solid var(--line); }
  .mobile-panel-tabs button { flex: 1; }
  .workspace-grid { display: block; min-height: 0; overflow: hidden; }
  .workspace-grid > .case-sidebar, .workspace-grid > .question-detail-wrap, .workspace-grid > .interview-panel { display: none; height: 100%; }
  .workspace-grid.mobile-questions > .case-sidebar { display: block; }
  .workspace-grid.mobile-answer > .question-detail-wrap { display: block; }
  .workspace-grid.mobile-interview > .interview-panel { display: flex; }
  .case-sidebar { width: 100%; }
  .question-detail-wrap { padding: 10px; }
  .integration-grid { grid-template-columns: 1fr; }
  .view-heading { align-items: flex-start; flex-direction: column; }
}

@media (max-width: 620px) {
  .topbar { gap: 8px; }
  .topbar-actions .secondary-button:nth-of-type(2), .topbar-actions .secondary-button:nth-of-type(3) { display: none; }
  .case-bar { padding: 7px 10px; }

  .case-sidebar { width: 100%; }
  .question-detail-wrap { padding: 10px; }
  .integration-grid { grid-template-columns: 1fr; }
  .view-heading { align-items: flex-start; flex-direction: column; }
}

@media (max-width: 620px) {
  .topbar { gap: 8px; }
  .topbar-actions .secondary-button:nth-of-type(2), .topbar-actions .secondary-button:nth-of-type(3) { display: none; }
  .case-bar { padding: 7px 10px; }
  .case-title strong { max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .review-banner { align-items: flex-start; flex-direction: column; gap: 2px; }
  .selection-topbar { padding: 0 4vw; }
  .selection-topbar .wordmark small { display: none; }
  .case-selection { margin-top: 5vh; }
  .new-case-card { align-items: flex-start; flex-direction: column; }
  .case-create-actions { width: 100%; }
  .case-create-actions button { width: 100%; }
  .form-grid { grid-template-columns: 1fr; }
  .form-grid .wide { grid-column: auto; }
  .source-meta { grid-template-columns: 1fr; }
  .receipt-meta { grid-template-columns: 1fr; }
  .receipt-meta div:first-child { grid-column: auto; }
  .audit-history li { grid-template-columns: 1fr; gap: 5px; }
}

export type AnswerStatus = "verified" | "employee_confirmed" | "partially_verified" | "conflicted" | "unknown";
export type Provenance = "company_information" | "user_confirmation" | "needs_confirmation";
export type SourceKind = "policy" | "configuration" | "message" | "report" | "employee";
export type UploadSourceKind = Exclude<SourceKind, "employee">;
export type SlotState = "answered" | "missing" | "deferred";
export type IntegrationState = "not_configured" | "ready" | "sent" | "manual_required" | "manual_recorded" | "error";

export interface Source {
  id: string;
  name: string;
  kind: SourceKind;
  scope: string;
  content: string;
  observedAt: string | null;
  createdAt: string;
  author: string | null;
}

export interface Citation { sourceId: string; quote: string; }

export interface Fact {
  id: string;
  key: string;
  scope: string;
  value: string;
  provenance: Provenance;
  citations: Citation[];
  updatedAt: string;
  supersedesFactId: string | null;
  active: boolean;
}

export interface MissingSlot {
  key: string;
  label: string;
  state: SlotState;
}

export interface Conflict {
  id: string;
  summary: string;
  citations: Citation[];
  state: "open" | "resolved";
  resolution: string | null;
  resolvedAt: string | null;
}

export interface FollowUp {
  id: string;
  slotKey: string;

  summary: string;
  citations: Citation[];
  state: "open" | "resolved";
  resolution: string | null;
  resolvedAt: string | null;
}

export interface FollowUp {
  id: string;
  slotKey: string;
  text: string;
  reason: string;
  suggestedOwner: string;
}

export interface Question {
  id: string;
  text: string;
  priority: number;
  scope: string;
  answer: string;
  status: AnswerStatus;
  provenance: Provenance;
  citations: Citation[];
  missingSlots: MissingSlot[];
  conflicts: Conflict[];
  followUp: FollowUp | null;
  updatedAt: string;
}

export interface Message {
  id: string;
  clientMessageId: string | null;
  questionId: string;
  role: "assistant" | "user";
  text: string;
  employeeName: string | null;
  employeeRole: string | null;
  createdAt: string;
}

export interface AuditEvent {
  id: string;
  kind: string;
  questionId: string | null;
  summary: string;
  createdAt: string;
}

export interface IntegrationReceipt {

export interface AuditEvent {
